def jp_ratio(s):
    if not s: return 0
    jp = len(re.findall(r'[぀-ヿ一-鿿]', s))
    return jp/max(len(s),1)

def try_fix(s):
    if not s:
        return s, False
    if jp_ratio(s) > 0.05:
        return s, False
    try:
        b = s.encode('latin-1')
    except Exception:
        return s, False
    best = None
    for enc in ['cp932','utf-8']:
        try:
            fixed = b.decode(enc)
            if jp_ratio(fixed) > 0.2:
                return fixed, True
        except Exception:
            continue
    # fallback with replace
    for enc in ['utf-8','cp932']:
        try:
            fixed = b.decode(enc, errors='replace')
            if jp_ratio(fixed) > 0.2:
                return fixed, True
        except Exception:
            continue
    return s, False

out = []
for d in data:
    title, ok1 = try_fix(d.get('title','') or '')
    desc, ok2 = try_fix(d.get('desc','') or '')
    body, ok3 = try_fix(d.get('body','') or '')
    d2 = dict(d)
    d2['title']=title; d2['desc']=desc; d2['body']=body
    d2['_fixed'] = ok1 or ok2 or ok3
    out.append(d2)

